package dk.starswordmaster.ui;
import dk.starswordmaster.progression.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class ResourceHudDataTest {
 private PlayerProgress fixture(){var props=new Properties();props.setProperty("xp","1355");props.setProperty("mana","42.5");props.setProperty("stamina","60.2");props.setProperty("stat.SPIRIT","5");props.setProperty("stat.ENDURANCE","3");return PlayerProgress.fromProperties(props);}
 @Test public void unavailableSnapshotDoesNotInventResources(){assertTrue(ResourceHudData.from(null,true,20,20,0).isEmpty());assertTrue(ResourceHudData.from(fixture(),false,20,20,0).isEmpty());}
 @Test public void takesLevelAndResourcesFromRealProgressAndHealthFromVanilla(){var p=fixture();var d=ResourceHudData.from(p,true,12.4,20.3,4).orElseThrow();assertEquals(p.level(),d.level());assertEquals(p.mana(),d.mana().current(),0);assertEquals(p.maxMana(),d.mana().maximum(),0);assertEquals(p.stamina(),d.stamina().current(),0);assertEquals(p.maxStamina(),d.stamina().maximum(),0);assertEquals(12.4,d.health().current(),0);assertEquals(20.3,d.health().maximum(),0);assertEquals(4,d.absorption(),0);assertEquals("12.4/20.3 +4",d.healthText());}
 @Test public void fullEmptyAndPartialBarsUseActualMaximum(){assertEquals(1,new ResourceHudData.Meter(40,40).fraction(),0);assertEquals(0,new ResourceHudData.Meter(0,40).fraction(),0);assertEquals(0.25,new ResourceHudData.Meter(10,40).fraction(),0);assertEquals(1,new ResourceHudData.Meter(45,40).fraction(),0);assertEquals("10/40",new ResourceHudData.Meter(10,40).text());}
 @Test public void missingOrInvalidResourceValuesAreUnavailable(){for(var meter:List.of(new ResourceHudData.Meter(10,0),new ResourceHudData.Meter(Double.NaN,20),new ResourceHudData.Meter(10,Double.POSITIVE_INFINITY),new ResourceHudData.Meter(-1,20))){assertEquals(0,meter.fraction(),0);assertEquals("—",meter.text());}}
 @Test public void snapshotRebuildReflectsDamageHealingCastingRegenerationAndLevel(){var p=fixture();assertTrue(p.unlock("spark"));assertTrue(p.assign(0,"spark"));var before=p.toProperties();var a=ResourceHudData.from(p,true,15,20,0).orElseThrow();assertEquals(before,p.toProperties());assertTrue(p.cast(0));var b=ResourceHudData.from(p,true,9,20,0).orElseThrow();assertTrue(b.mana().current()<a.mana().current());assertEquals(9,b.health().current(),0);p.tick(false);var c=ResourceHudData.from(p,true,18,20,0).orElseThrow();assertTrue(c.mana().current()>b.mana().current());assertEquals(18,c.health().current(),0);var higher=p.toProperties();higher.setProperty("xp","1700");var next=ResourceHudData.from(PlayerProgress.fromProperties(higher),true,18,20,0).orElseThrow();assertTrue(next.level()>c.level());assertTrue(next.mana().maximum()>c.mana().maximum());}
 @Test public void viewingAndReloadingPreserveProgressionAndResources(){var p=fixture();var before=p.toProperties();var a=ResourceHudData.from(p,true,20.6,21.1,2).orElseThrow();for(int i=0;i<100;i++)ResourceHudData.from(p,true,20.6,21.1,2);assertEquals(before,p.toProperties());var b=ResourceHudData.from(PlayerProgress.fromProperties(before),true,20.6,21.1,2).orElseThrow();assertEquals(a,b);}
}
